#' Single Group Norming
#'
#' 
#' @param data the data as a data frame
#' @param raw a string specifying the raw score variable in \code{data}
#' @param weights an optional weighting variable specifying the weights of the
#'   single cases
#' @param scale \code{'T'}, \code{'IQ'}, \code{'z'}, \code{'Wechsler'} (m =
#'   10, sd = 3), or \code{'PISA'} (m = 500, sd = 100)
#' @param descend .
#' @param k .
#' @param kPower .
#' @param selectionType .
#' @param terms .
#' @param plotting .
#' @param model .
#' @param range .
#' @param minRaw .
#' @param maxRaw .
#' @param stepping .
#' @param includeCI .
#' @param ciLevel .
#' @param reliability .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$modelFit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$modelCoef} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$norms} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$saveManifest} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$saveManifestPerc} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$savePredicted} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$savePredictedPerc} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$modelFit$asDF}
#'
#' \code{as.data.frame(results$modelFit)}
#'
#' @export
conventional <- function(
    data,
    raw,
    weights,
    scale = "T",
    descend = FALSE,
    k = TRUE,
    kPower = "5",
    selectionType = "automaticSelection",
    terms = 4,
    plotting = "Norm Score",
    model = TRUE,
    range = 3,
    minRaw = 0,
    maxRaw = 0,
    stepping = 1,
    includeCI = FALSE,
    ciLevel = 0.9,
    reliability = 0.9) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("conventional requires jmvcore to be installed (restart may be required)")

    if ( ! missing(raw)) raw <- jmvcore::resolveQuo(jmvcore::enquo(raw))
    if ( ! missing(weights)) weights <- jmvcore::resolveQuo(jmvcore::enquo(weights))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(raw), raw, NULL),
            `if`( ! missing(weights), weights, NULL))


    options <- conventionalOptions$new(
        raw = raw,
        weights = weights,
        scale = scale,
        descend = descend,
        k = k,
        kPower = kPower,
        selectionType = selectionType,
        terms = terms,
        plotting = plotting,
        model = model,
        range = range,
        minRaw = minRaw,
        maxRaw = maxRaw,
        stepping = stepping,
        includeCI = includeCI,
        ciLevel = ciLevel,
        reliability = reliability)

    analysis <- conventionalClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

